<script setup lang="ts">
import {computed} from 'vue'
import {Info,ArrowUpRight,Activity,Wine,Cigarette,Wallet,Heart,ChevronRight,BookOpen} from 'lucide-vue-next'
import Chart from './Chart.vue'
import AlcoholEstimate from './AlcoholEstimate.vue'
import AssociationSummary from './AssociationSummary.vue'
import AssociationDetails from './AssociationDetails.vue'
import {state} from '../api'
import {money,number,shortDate} from '../types'
const props=defineProps<{from:string;to:string}>();const emit=defineEmits<{view:[page:string];repair:[detail:Record<string,any>]}>()
const total=computed(()=>state.analytics.totals||{}),alcohol=computed(()=>state.analytics.alcohol||{}),daily=computed(()=>state.analytics.daily||[])
const health=computed(()=>state.health?.length?state.health:state.collections.health||[])
const expenseOption=computed<any>(()=>({animation:!state.settings.reducedMotion,tooltip:{trigger:'item',backgroundColor:'#252631',borderColor:'#353743',textStyle:{color:'#eee'},formatter:(p:any)=>`${p.name}<br/>${money(p.value)}`},legend:{bottom:5,textStyle:{color:'#8b8e9c'},icon:'circle'},series:[{type:'pie',radius:['58%','78%'],center:['50%','44%'],label:{show:false},itemStyle:{borderColor:'#1a1b23',borderWidth:5,borderRadius:8},data:[{name:'吸烟已知成本',value:total.value.smokingCost,itemStyle:{color:'#a8e6ba'}},{name:'饮酒已知成本',value:total.value.alcoholCost,itemStyle:{color:'#9aabff'}}].filter(d=>d.value!=null)}]}))
const volumeOption=computed<any>(()=>({animation:!state.settings.reducedMotion,grid:{left:43,right:22,top:25,bottom:28},tooltip:{trigger:'axis',backgroundColor:'#252631',borderColor:'#353743',textStyle:{color:'#eee'}},xAxis:{type:'category',data:daily.value.map(d=>String(d.date).slice(5)),axisLabel:{color:'#878b99'},axisLine:{lineStyle:{color:'#343540'}},axisTick:{show:false}},yAxis:{type:'value',name:'ml',nameTextStyle:{color:'#878b99'},axisLabel:{color:'#878b99'},splitLine:{lineStyle:{color:'#292b35',type:'dashed'}}},series:[{type:'bar',name:'折合42°白酒',barMaxWidth:18,itemStyle:{color:'#9aabff',borderRadius:[5,5,0,0]},data:daily.value.map(d=>d.ethanolEquivalent42Ml)}]}))
const smokeRows=computed(()=>(state.collections.smoking||[]).filter(r=>String(r.occurredAt).slice(0,10)>=props.from&&String(r.occurredAt).slice(0,10)<=props.to))
function coverage(key:string){return smokeRows.value.filter(r=>r[key]!=null).reduce((s,r)=>s+Number(r.count||0),0)}
</script>
<template><div class="analytics-page"><div class="analytics-summary"><div><span class="eyebrow">UNDERSTAND YOUR PATTERNS</span><h2>让变化有据可看。</h2><p>{{shortDate(from)}} 至 {{shortDate(to)}} · 未记录日期按 0，补记后自动更新。</p></div><span class="tag mint"><Activity :size="14"/>真实记录汇总</span></div><AssociationSummary/><div class="analytics-grid"><section class="panel"><header class="panel-header"><div><span class="eyebrow">CONSUMPTION COST</span><h3>按用量计算的烟酒花费</h3></div><Wallet :size="20" class="muted"/></header><div class="donut-wrap sensitive"><Chart :option="expenseOption" label="按种类单价与本人用量计算的烟酒花费"/><div class="donut-label"><span>已知小计</span><strong>{{money(total.consumptionCost)}}</strong></div></div><div class="cost-facts"><div class="cost-breakdown sensitive"><span>吸烟 <strong>{{money(total.smokingCost)}}</strong></span><span>饮酒 <strong>{{money(total.alcoholCost)}}</strong></span></div><p>按所选种类的单价 × 本人用量计算。价格缺失的记录保留为待补，不按零元计入。</p></div></section><section class="panel"><header class="panel-header"><div><span class="eyebrow">SAME ALCOHOL, CLEARER MEASURE</span><h3>折合 42° 白酒</h3></div><span class="tag alcohol sensitive">{{total.ethanolEquivalent42Ml==null?'待补资料':number(total.ethanolEquivalent42Ml)+' ml'}}</span></header><div class="analytics-chart sensitive"><Chart :option="volumeOption" label="每天的饮酒量折合为42度白酒毫升数"/></div><footer class="chart-footer alcohol-conversion-note"><span>按纯酒精量换算，便于比较不同酒品</span><span class="sensitive">纯酒精 {{total.ethanolGrams==null?'待补资料':number(total.ethanolGrams)+' g'}}</span></footer><p class="conversion-formula">换算：纯酒精克数 ÷ 0.789 ÷ 42% = 42° 白酒毫升数</p></section></div>
<AlcoholEstimate @view="emit('view',$event)" @repair="emit('repair',$event)"/>
<section class="panel constituent-panel"><header class="panel-header"><div><span class="eyebrow">LABELLED CONSTITUENTS</span><h3>烟盒标示成分折算</h3></div><Cigarette :size="21" class="muted"/></header><div class="constituent-metrics sensitive"><div v-for="m in [{key:'smokingTarMg',snapshot:'snapshotTarMg',label:'焦油'},{key:'smokingNicotineMg',snapshot:'snapshotNicotineMg',label:'烟气烟碱'},{key:'smokingCoMg',snapshot:'snapshotCoMg',label:'烟气一氧化碳'}]" :key="m.key"><span>{{m.label}} · 标示值合计</span><strong>{{total.constituentMixedMethods?'分口径':total[m.key]!=null&&coverage(m.snapshot)?number(total[m.key],2):'—'}}<small>mg</small></strong><p>有标示资料 {{coverage(m.snapshot)}} / {{total.smokingCount||0}} 根</p></div></div><div v-if="total.tobaccoByMethod?.length" class="table-scroll constituent-groups"><table><thead><tr><th>标示 / 检测口径</th><th>焦油 mg</th><th>烟气烟碱 mg</th><th>一氧化碳 mg</th></tr></thead><tbody><tr v-for="g in total.tobaccoByMethod" :key="g.method"><td>{{g.method||'未说明口径'}}</td><td>{{g.tarMg==null?'待补资料':number(g.tarMg,2)}}<small class="muted"> · {{g.tarCoveredCount}} 根</small></td><td>{{g.nicotineMg==null?'待补资料':number(g.nicotineMg,2)}}<small class="muted"> · {{g.nicotineCoveredCount}} 根</small></td><td>{{g.coMg==null?'待补资料':number(g.coMg,2)}}<small class="muted"> · {{g.coCoveredCount}} 根</small></td></tr></tbody></table></div><div class="soft-notice"><Info :size="17"/><span>以上为包装标示值乘以根数，不是人体吸收量或体内残留量。低焦油不代表更安全，不同检测口径不宜直接比较。</span></div></section>
<AssociationDetails :from="from" :to="to"/>
<div v-if="state.analytics.warnings?.length" class="soft-notice"><Info :size="18"/><div><p v-for="(w,i) in state.analytics.warnings" :key="i">{{typeof w==='string'?w:w.message||JSON.stringify(w)}}</p></div></div><div class="health-grid"><article v-for="h in health" :key="h.id||h.title" class="panel health-card"><BookOpen :size="21"/><h3>{{h.title}}</h3><p>{{h.body}}</p><a v-if="h.sourceUrl" class="text-link" :href="h.sourceUrl" target="_blank" rel="noopener noreferrer">阅读来源 <ArrowUpRight :size="15"/></a></article></div></div></template>
